# AUTO-GENERATED by Claude Code
# Purpose: enforces "Platforms" in spec/services/ui/README.md: the app (services/ui) and the
#          `ds` package run on Linux (Omarchy) and on Windows. Checked here, on Linux: the
#          repo's code reads and writes text as UTF-8 by name (Windows' default is not UTF-8),
#          a Unix-only module is only imported where its absence is handled, and the whole app
#          imports when this repo's code can't import them (a stand-in for Windows: it is not a
#          run on Windows).
# Usage: uv run pytest tests/test_cross_platform.py
# ---------------------------------------------------------------------------
from __future__ import annotations

import ast
import subprocess
import sys
from pathlib import Path

import pytest

REPO = Path(__file__).resolve().parents[1]
APP_DIR = REPO / "services" / "ui"
SCANNED = (REPO / "pkgs" / "ds", APP_DIR / "ui")
# stdlib modules Windows doesn't have
UNIX_ONLY = {"fcntl", "pty", "termios", "tty", "resource", "pwd", "grp", "syslog", "curses", "readline"}
TEXT_CALLS = {"read_text", "write_text"}


def _trees() -> list[tuple[Path, ast.Module]]:
    files = [path for folder in SCANNED for path in folder.rglob("*.py") if "__pycache__" not in path.parts]
    return [(path, ast.parse(path.read_text(encoding="utf-8"))) for path in files]


def _where(path: Path, node: ast.AST) -> str:
    return f"{path.relative_to(REPO)}:{getattr(node, 'lineno', 0)}"


def _text_mode(call: ast.Call) -> bool:
    """Whether an open(...) call opens text: its mode (a literal) has no "b"."""
    builtin = isinstance(call.func, ast.Name)
    modes = [keyword.value for keyword in call.keywords if keyword.arg == "mode"]
    position = 1 if builtin else 0  # open(file, mode) / path.open(mode)
    if not modes and len(call.args) > position:
        modes = [call.args[position]]
    if not modes:
        return True  # the default mode, "r"
    mode = modes[0]
    return isinstance(mode, ast.Constant) and isinstance(mode.value, str) and "b" not in mode.value


def test_text_files_are_read_and_written_as_utf8_by_name() -> None:
    # without encoding=, Windows uses its own code page: a "…" or "✨" in a file then fails
    missing = []
    for path, tree in _trees():
        for node in ast.walk(tree):
            if not isinstance(node, ast.Call) or any(keyword.arg == "encoding" for keyword in node.keywords):
                continue
            func = node.func
            if isinstance(func, ast.Attribute) and func.attr in TEXT_CALLS:
                missing.append(_where(path, node))
            # the builtin, and a path's own .open("a"); not os.open, webbrowser.open, ...
            opens_file = (isinstance(func, ast.Name) and func.id == "open") or (
                isinstance(func, ast.Attribute)
                and func.attr == "open"
                and not (
                    isinstance(func.value, ast.Name) and func.value.id in {"os", "webbrowser", "tarfile", "zipfile"}
                )
                and (not node.args or isinstance(node.args[0], ast.Constant))
            )
            if opens_file and _text_mode(node):
                missing.append(_where(path, node))
    assert not missing, f'pass encoding="utf-8": {", ".join(sorted(missing))}'


def test_a_unix_only_module_is_only_imported_where_its_absence_is_handled() -> None:
    # at a module's top level it must sit in `try: ... except ImportError`, else the module
    # (and the app, which imports it) can't load on Windows
    bare = []
    for path, tree in _trees():
        for node in tree.body:
            names = (
                [alias.name for alias in node.names]
                if isinstance(node, ast.Import)
                else [node.module or ""]
                if isinstance(node, ast.ImportFrom)
                else []
            )
            bare += [f"{_where(path, node)} ({name})" for name in names if name.split(".")[0] in UNIX_ONLY]
    assert not bare, f"wrap in try/except ImportError and handle the absence: {', '.join(bare)}"


# Run in a process of its own: this repo's code can't import the Unix-only modules there. The
# libraries keep theirs: they choose by sys.platform, which can't be changed (the stdlib
# itself reads it).
STAND_IN = """
import importlib.abc, sys
REPO, UNIX_ONLY = sys.argv[1], set(sys.argv[2].split(","))
class Block(importlib.abc.MetaPathFinder):
    def find_spec(self, name, path=None, target=None):
        if name.split(".")[0] not in UNIX_ONLY:
            return None
        frame = sys._getframe(1)
        while frame and "importlib" in frame.f_code.co_filename:
            frame = frame.f_back
        file = frame.f_code.co_filename if frame else ""
        if file.startswith((REPO + "/pkgs", REPO + "/services")):
            raise ImportError(f"No module named {name!r} (as on Windows), imported by {file}")
        return None
for name in UNIX_ONLY:
    sys.modules.pop(name, None)
sys.meta_path.insert(0, Block())
import ds.cli.__main__  # the `ds` command
import ui.ui, ui.state, ui.api  # the whole app, as `reflex run` imports it
import asyncio
from ui import terminal
assert terminal.AVAILABLE is False
assert "isn't available on Windows" in asyncio.run(terminal.page(None)).body.decode()
"""


def test_the_app_imports_without_the_unix_only_modules() -> None:
    done = subprocess.run(  # this interpreter, the fixed code above
        [sys.executable, "-c", STAND_IN, str(REPO), ",".join(sorted(UNIX_ONLY))],
        cwd=APP_DIR,
        capture_output=True,
        text=True,
        timeout=180,
        check=False,
    )
    assert done.returncode == 0, done.stderr[-1200:]


@pytest.mark.parametrize("name", ["tzdata"])
def test_what_only_windows_needs_is_a_dependency(name: str) -> None:
    # zoneinfo has no time zone data on Windows without it (the Spend view's days)
    pyproject = (REPO / "pyproject.toml").read_text(encoding="utf-8")
    assert f'"{name}' in pyproject
    assert "sys_platform == 'win32'" in pyproject
